// This file is not generated by Speakeasy — it is the attribution the browser
// login adds to the authorization URL.
//
// Growth attributes signups by UTM parameters, so the authorization URL the
// CLI opens carries the CLI's campaign. utm_content tells a signup from an
// ordinary sign-in, and cli_agent records which coding agent, if any, ran the
// command, so signups driven by AI agents can be counted. The authorization
// server passes them on to the login and signup pages; servers that do not
// know them ignore them.

package oauth

import (
	"net/url"
	"strings"
)

const (
	// CLIAgentNone is the cli_agent value when no coding agent was detected.
	CLIAgentNone = "none"

	utmContentSignup = "signup"
	utmContentLogin  = "login"
)

// cliAgents maps the environment variables known coding agents set to the
// cli_agent value reported for them, checked in order. It covers the agents
// output.agentEnvVars detects, plus the variables Codex actually sets
// (CODEX_SANDBOX in its sandbox, CODEX_THREAD_ID in its shell tool), which
// are not truthy flags and so need only to be non-empty here.
var cliAgents = []struct {
	envVar string
	agent  string
	// anyValue counts the variable as set when it is non-empty, rather than
	// only when it is a truthy flag.
	anyValue bool
}{
	{envVar: "CLAUDECODE", agent: "claude_code"},
	{envVar: "CLAUDE_CODE", agent: "claude_code"},
	{envVar: "CODEX", agent: "codex"},
	{envVar: "CODEX_SANDBOX", agent: "codex", anyValue: true},
	{envVar: "CODEX_THREAD_ID", agent: "codex", anyValue: true},
	{envVar: "CURSOR_AGENT", agent: "cursor"},
	{envVar: "AIDER", agent: "aider"},
	{envVar: "CLINE", agent: "cline"},
	{envVar: "WINDSURF_AGENT", agent: "windsurf"},
	{envVar: "GITHUB_COPILOT", agent: "github_copilot"},
	{envVar: "AMAZON_Q", agent: "amazon_q"},
	{envVar: "GEMINI_CODE_ASSIST", agent: "gemini_code_assist"},
	{envVar: "SRC_CODY", agent: "cody"},
}

// detectCLIAgent names the coding agent running the CLI, from its environment,
// or CLIAgentNone. It reports the environment rather than agent mode, which
// --agent-mode and FORCE_AGENT_MODE can turn on or off by hand.
func detectCLIAgent(getenv func(string) string) string {
	for _, a := range cliAgents {
		value := strings.TrimSpace(getenv(a.envVar))
		if a.anyValue && value != "" {
			return a.agent
		}
		switch strings.ToLower(value) {
		case "1", "true", "yes":
			return a.agent
		}
	}
	return CLIAgentNone
}

// trackingParams are the attribution parameters for an authorization URL.
// prompt is the prompt actually sent, so a signup the server could not offer
// is recorded as the login it became.
func trackingParams(prompt, agent string) url.Values {
	content := utmContentLogin
	if prompt == PromptCreate {
		content = utmContentSignup
	}
	return url.Values{
		"utm_source":   {"voiceflow_cli"},
		"utm_medium":   {"product"},
		"utm_campaign": {"cli_signup"},
		"utm_content":  {content},
		"cli_agent":    {agent},
	}
}
